    const scores = { d: 0, i: 0, s: 0, c: 0 };
    const majCount = { d: 0, i: 0, s: 0, c: 0 };
    const minCount = { d: 0, i: 0, s: 0, c: 0 };

    // Iterate through all questions and all cards
    QUESTIONS.forEach((_, qIdx) => {
        qIdx.cards.forEach((card, cIdx) => {
            const list = document.getElementById(`list-${qIdx}-${cIdx}`);
            const items = Array.from(list.children);

            items.forEach((item, pos) => {
                const type = item.dataset.type;
                if (pos === 0) majCount[type]++;
                if (pos === 3) minCount[type]++;
            });
        });
    });

    // Apply scoring formula (difference between major and minor)
    scores.d = majCount.d - minCount.d;
    scores.i = majCount.i - minCount.i;
    scores.s = majCount.s - minCount.s;
    scores.c = majCount.c - minCount.c;

    showResults(scores);
}

